const h1 = code.match(/<h1\s*>/gi) ?? [];
if (h1.length !== 1) {
  throw new Error(`Found ${h1.length} <h1> elements — a page has exactly one main heading.`);
}

const h2 = code.match(/<h2\s*>/gi) ?? [];
if (h2.length < 2) {
  throw new Error("An article outline needs at least two <h2> section headings.");
}

const firstH2 = code.search(/<h2\s*>/i);
const firstH3 = code.search(/<h3\s*>/i);
if (firstH3 === -1 || firstH3 < firstH2) {
  throw new Error("Place an <h3> after your first <h2> — sub-headings nest under section headings, never before them.");
}

const ends = [...code.matchAll(/<h[123][\s\S]*?<\/h[123]>/gi)].map((m) => m.index + m[0].length);
ends.push(code.length);
for (let i = 0; i < ends.length - 1; i++) {
  const section = code.slice(ends[i], ends[i + 1]);
  if (!/<p>[\s\S]*?<\/p>/i.test(section)) {
    throw new Error("Every heading should be followed by its own <p> before the next heading starts.");
  }
}
